-- 000048_express_hysteria2.up.sql
-- Express routing — Hysteria2 client inbound on the Hub for premium plans.
-- Adds per-user auth password and per-plan Brutal bandwidth limits.
-- Server-side config is generated by cmd/api/hysteria2_sync.go, the systemd unit
-- hysteria2-server.service runs on the Hub and authenticates via an HTTP backend
-- at POST 127.0.0.1:8000/internal/hysteria2/auth.

-- Per-user Hysteria2 password (separate from VLESS UUID — different protocol, different secret).
-- 32 random bytes hex-encoded → 64 chars. Lazy-filled on first GetUserHysteria2Password call.
ALTER TABLE users ADD COLUMN IF NOT EXISTS hysteria2_password VARCHAR(64) NOT NULL DEFAULT '';

-- Per-plan Express toggle and Brutal bandwidth limits (Mbps). Brutal needs explicit
-- up/down targets; setting them per-plan lets the same Hub serve different tiers.
ALTER TABLE plans ADD COLUMN IF NOT EXISTS express_enabled    BOOLEAN NOT NULL DEFAULT FALSE;
ALTER TABLE plans ADD COLUMN IF NOT EXISTS express_up_mbps    INTEGER NOT NULL DEFAULT 50;
ALTER TABLE plans ADD COLUMN IF NOT EXISTS express_down_mbps  INTEGER NOT NULL DEFAULT 100;

-- Seed: enable Express on top-tier plans and add 'hysteria2' to allowed_protocols.
-- all-inclusive: 50/100 Mbps (default), annual-premium: 100/200 Mbps.
UPDATE plans
SET express_enabled   = TRUE,
    express_up_mbps   = 50,
    express_down_mbps = 100,
    allowed_protocols = (
        SELECT ARRAY(SELECT DISTINCT unnest(allowed_protocols || ARRAY['hysteria2']))
    )
WHERE slug = 'all-inclusive';

UPDATE plans
SET express_enabled   = TRUE,
    express_up_mbps   = 100,
    express_down_mbps = 200,
    allowed_protocols = (
        SELECT ARRAY(SELECT DISTINCT unnest(allowed_protocols || ARRAY['hysteria2']))
    )
WHERE slug = 'annual-premium';

-- App-settings: Salamander obfuscation password (shared across all users — it's a stream-level obfuscation,
-- not per-user auth). Generated lazily by biz.GetHysteria2ObfsPassword on first call.
INSERT INTO app_settings (key, value)
VALUES ('hysteria2_obfs_password', '')
ON CONFLICT (key) DO NOTHING;

-- App-settings: config version so admin UI / sync loop can detect changes.
INSERT INTO app_settings (key, value)
VALUES ('hysteria2_config_version', '1')
ON CONFLICT (key) DO NOTHING;
